-- Rollback 238: remove the ten inserted BECE beta questions; preserve remediation history.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _expected_238 (question_id TEXT PRIMARY KEY, topic_id TEXT NOT NULL, subject_id TEXT NOT NULL, exam_type_id TEXT NOT NULL, question_text TEXT NOT NULL, question_type TEXT NOT NULL, options TEXT NOT NULL, correct_answer TEXT NOT NULL, explanation TEXT NOT NULL, difficulty TEXT NOT NULL, points INTEGER NOT NULL, marks INTEGER NOT NULL, time_limit INTEGER NOT NULL, command_word TEXT NOT NULL, assessment_objective TEXT NOT NULL);
DELETE FROM _expected_238;
INSERT INTO _expected_238(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_bdt_gap_b001_011','topic_bece_bdt_construction','subj_bece_bdt','exam_bece','A square card frame collapses sideways during testing. Which improvement directly addresses the weakness?','multiple_choice','["A. Cut away one complete side","B. Make the corner holes much larger","C. Add a diagonal brace between opposite corners","D. Attach a loose label to the centre"]','C','The diagonal converts the flexible square into triangular regions and provides a direct member to resist the sideways force causing the frame to rack. Therefore the correct answer is C: Add a diagonal brace between opposite corners.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_012','topic_bece_bdt_construction','subj_bece_bdt','exam_bece','Which procedure is safest when cutting thin wood for a class structure project?','multiple_choice','["A. Hold the wood in the air near the blade","B. Cut toward the supporting hand","C. Skip measurement and force the tool","D. Mark the cut, secure the wood and cut away from the body"]','D','Accurate marking, firm support and a cutting direction away from the body reduce slipping, poor fit and injury during a simple construction task. Therefore the correct answer is D: Mark the cut, secure the wood and cut away from the body.','medium',1,1,90,'Apply','AO2'),
  ('q_bece_bdt_gap_b001_013','topic_bece_bdt_construction','subj_bece_bdt','exam_bece','A glued joint in a model frame separates during a load test. What should the learner investigate first?','multiple_choice','["A. Whether the frame colour was bright enough","B. Whether the ruler had printed numbers","C. Whether the surfaces were clean, fitted and allowed to set","D. Whether unused card was stored nearby"]','C','Adhesive joints depend on suitable clean contact surfaces, close fit and enough setting time, so these process conditions should be checked before redesigning the frame. Therefore the correct answer is C: Whether the surfaces were clean, fitted and allowed to set.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_014','topic_bece_bdt_construction','subj_bece_bdt','exam_bece','How should learners compare two model bridge designs fairly?','multiple_choice','["A. Use different loads and make no records","B. Apply the same increasing load and record when each design deforms","C. Judge only by colour","D. Test one bridge on a table and throw the other"]','B','A fair test controls the loading method and records deformation or failure, producing evidence about how efficiently each structure supports the intended load. Therefore the correct answer is B: Apply the same increasing load and record when each design deforms.','hard',1,1,90,'Apply','AO3'),
  ('q_bece_bdt_gap_b001_015','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','A 3 A appliance is fitted with a 5 A fuse. Why would replacing it with a 13 A fuse reduce protection?','multiple_choice','["A. The higher-rated fuse may not melt before the appliance wiring overheats","B. The higher-rated fuse always lowers supply voltage","C. A 13 A fuse stores dangerous current after switch-off","D. The appliance will immediately use exactly 13 A"]','A','A fuse rating should be just above normal operating current but below the level that the appliance cable can safely carry, so an oversized fuse may permit damaging current. Therefore the correct answer is A: The higher-rated fuse may not melt before the appliance wiring overheats.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_016','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','Which wire should a single-pole light switch interrupt?','multiple_choice','["A. The live wire","B. The earth wire","C. Live and neutral joined","D. A disconnected spare wire"]','A','Interrupting the live conductor isolates dangerous voltage from the lamp holder when off; switching only neutral can leave parts live. Therefore the correct answer is A: The live wire.','medium',1,1,90,'Identify','AO2'),
  ('q_bece_bdt_gap_b001_017','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','A fault makes the metal case of a kettle live. Which sequence explains how earthing protects a user?','multiple_choice','["A. The earth wire raises the case voltage safely","B. Normal load current is stored in the metal case","C. Fault current flows through earth and causes the protective device to disconnect","D. The neutral wire is removed so the case remains live"]','C','The low-resistance earth path carries a large fault current that makes the fuse or circuit breaker operate, disconnecting the supply instead of leaving exposed metal live. Therefore the correct answer is C: Fault current flows through earth and causes the protective device to disconnect.','hard',1,1,90,'Explain','AO3'),
  ('q_bece_bdt_gap_b001_018','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','Why are household lamps normally connected in parallel?','multiple_choice','["A. They must share one small voltage","B. One failure must stop all lamps","C. Parallel wiring blocks current","D. Each receives supply voltage and can operate independently"]','D','Parallel branches place each lamp across the supply, so each receives intended voltage and another branch can continue independently. Therefore the correct answer is D: Each receives supply voltage and can operate independently.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_019','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','Which material suitably covers a flexible copper appliance cord?','multiple_choice','["A. Bare steel wool","B. Electrical-grade plastic insulation","C. Wet cotton thread","D. Aluminium foil"]','B','Electrical-grade plastic resists current flow and bends with the cable, reducing accidental contact with the conducting copper core. Therefore the correct answer is B: Electrical-grade plastic insulation.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_bdt_gap_b001_020','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','What condition most directly causes a socket circuit overload?','multiple_choice','["A. The room has many chairs","B. Appliances demand more current than the circuit is rated to carry","C. A lamp is off","D. The earth wire is coloured correctly"]','B','An overload occurs when combined appliance current exceeds the safe rating of conductors or protection, causing dangerous heating. Therefore the correct answer is B: Appliances demand more current than the circuit is rated to carry.','medium',1,1,90,'Explain','AO2');
CREATE TABLE IF NOT EXISTS _rollback_238_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _rollback_238_guard;
INSERT INTO _rollback_238_guard(valid) SELECT CASE WHEN
  NOT EXISTS (SELECT 1 FROM questions q JOIN _expected_238 e ON e.question_id=q.id WHERE NOT (q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective))
  AND NOT EXISTS (SELECT 1 FROM question_content_releases r JOIN _expected_238 e ON e.question_id=r.question_id WHERE NOT (r.batch_id IS 'bece-bdt-gap-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1))
  AND NOT EXISTS (SELECT 1 FROM question_bank_remediation_log l JOIN _expected_238 e ON e.question_id=l.entity_id WHERE l.migration_id='238_bece_bdt_gap_beta_part_2' AND NOT (l.migration_id IS '238_bece_bdt_gap_beta_part_2' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-bdt-gap-beta-001'))
  AND (((SELECT COUNT(*) FROM questions q JOIN _expected_238 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_238 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-bdt-gap-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_238 e ON e.question_id=l.entity_id WHERE l.migration_id IS '238_bece_bdt_gap_beta_part_2' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-bdt-gap-beta-001')=10)
    OR ((SELECT COUNT(*) FROM questions q JOIN _expected_238 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_238 e ON e.question_id=r.question_id)=0 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_238 e ON e.question_id=l.entity_id WHERE l.migration_id='238_bece_bdt_gap_beta_part_2') IN (0,10)))
THEN 1 ELSE 0 END;
DELETE FROM questions WHERE id IN (SELECT question_id FROM _expected_238);
INSERT INTO _rollback_238_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _expected_238 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_238 e ON e.question_id=r.question_id)=0 THEN 1 ELSE 0 END;
DROP TABLE _expected_238;
DROP TABLE _rollback_238_guard;
